}

type Product = { id: string; title: string };

export function ProductList({ data }: { data: Product[] }) {
  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id}
      renderItem={(item) => <Text>{item.title}</Text>}
    />
  );
}

export function TaskList({ tasks, onDelete }: Props) {
  return (
    <FlatList
      data={tasks}
      keyExtractor={(item, index) => String(index)}
      renderItem={({ item }) => (
        <TaskRow task={item} onDelete={() => onDelete(item.id)} />
      )}
    />
  );
}

function TaskRow({ task, onDelete }: RowProps) {
  const [done, setDone] = useState(false);
  return (
    <View>
      <Text>{task.title}</Text>
      <Switch value={done} onValueChange={setDone} />
      <Button title="Xoá" onPress={onDelete} />
    </View>
  );
}

export function CityPicker({ cities }: { cities: City[] }) {
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const renderItem = useCallback(({ item }: { item: City }) => (
    <Pressable onPress={() => setSelectedId(item.id)}>
      <Text style={{ color: item.id === selectedId ? 'tomato' : 'black' }}>
        {item.name}
      </Text>
    </Pressable>
  ), []);

  return (
    <FlatList
      data={cities}
      keyExtractor={(c) => c.id}
      renderItem={renderItem}
    />
  );
}

